	public static String getName(String code)  {
		return ACADEMIC_TITULATION.get(code);
	}
	
	public static Map<String, String> getProvinces() {
		return ACADEMIC_TITULATION;
	} 
	
	public static Map<String, String> getAcademicTitulations( String type ) {
		Map<String, String> newMap = new HashMap<String, String>();
		for(Entry<String, String> e : ACADEMIC_TITULATION.entrySet()) {
			if(e.getKey().substring(0, 2).equals(type) || e.getKey().substring(0, 2) == type) 
				newMap.put(e.getKey(), e.getValue());
		}
		return newMap;
	}

